package local.station.controller;

import java.io.*;import java.net.*;import java.nio.*;import java.math.BigInteger;import java.security.*;import java.security.interfaces.RSAPublicKey;import javax.crypto.Cipher;

/** Minimal direct ADB transport: no local ADB server, external executable or phone root. */
final class NativeAdb implements Closeable {
 static final int CNXN=0x4e584e43,AUTH=0x48545541,OPEN=0x4e45504f,OKAY=0x59414b4f,WRTE=0x45545257,CLSE=0x45534c43;
 private final Socket socket;private final DataInputStream in;private final OutputStream out;private int remote,maxData=4096;private boolean closed;private ByteArrayOutputStream pending=new ByteArrayOutputStream();private int cursor;
 static final class Packet{int command,a,b;byte[] data;Packet(int c,int x,int y,byte[] d){command=c;a=x;b=y;data=d;}}
 NativeAdb(String host,int port,KeyPair key)throws Exception{this(host,port,key,null);}
 NativeAdb(String host,int port,KeyPair key,android.net.Network network)throws Exception{
  InetAddress ip=InetAddress.getByName(host);if(!(ip instanceof Inet4Address)||!ip.isSiteLocalAddress()||!host.matches("[0-9.]+")||port<1||port>65535)throw new IOException("Нужны локальный IPv4-адрес и порт ADB");
  socket=new Socket();if(network!=null)network.bindSocket(socket);socket.connect(new InetSocketAddress(ip,port),5000);socket.setSoTimeout(30000);socket.setTcpNoDelay(true);in=new DataInputStream(socket.getInputStream());out=socket.getOutputStream();
  try{send(CNXN,0x01000000,256*1024,"host::\0".getBytes("UTF-8"));boolean signed=false,published=false;for(int tries=0;tries<4;tries++){Packet p=receive();if(p.command==CNXN){maxData=Math.max(1024,Math.min(256*1024,p.b));return;}if(p.command!=AUTH||p.a!=1||p.data.length!=20)throw new IOException("Ответ не похож на ADB");if(!signed){byte[] prefix=new byte[]{0x30,0x21,0x30,0x09,0x06,0x05,0x2b,0x0e,0x03,0x02,0x1a,0x05,0x00,0x04,0x14};ByteArrayOutputStream b=new ByteArrayOutputStream();b.write(prefix);b.write(p.data);Cipher cipher=Cipher.getInstance("RSA/ECB/PKCS1Padding");cipher.init(Cipher.ENCRYPT_MODE,key.getPrivate());send(AUTH,2,0,cipher.doFinal(b.toByteArray()));signed=true;}else if(!published){send(AUTH,3,0,(base64(adbPublic((RSAPublicKey)key.getPublic()))+" kontur@android\0").getBytes("US-ASCII"));published=true;}else throw new IOException("Разрешите ADB для телефона на станции и повторите проверку");}throw new IOException("ADB не подтвердил подключение");}catch(java.net.SocketTimeoutException e){socket.close();throw new IOException("ADB не подтвердил подключение. Разрешите телефон в запросе отладки на станции или проверьте авторизацию в AliceBridge.");}catch(Exception e){socket.close();throw e;}
 }
 void reboot()throws IOException{send(OPEN,1,0,"reboot:\0".getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 void timeout(int milliseconds)throws IOException{socket.setSoTimeout(milliseconds);}
 private void send(int command,int a,int b,byte[] data)throws IOException{int sum=0;for(byte v:data)sum+=v&255;ByteBuffer h=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN);h.putInt(command).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(command^0xffffffff);out.write(h.array());out.write(data);out.flush();}
 private Packet receive()throws IOException{byte[] raw=new byte[24];in.readFully(raw);ByteBuffer h=ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN);int c=h.getInt(),a=h.getInt(),b=h.getInt(),len=h.getInt(),sum=h.getInt(),magic=h.getInt();if(magic!=(c^0xffffffff)||len<0||len>1024*1024)throw new IOException("Неверный пакет ADB");byte[] data=new byte[len];in.readFully(data);int actual=0;for(byte v:data)actual+=v&255;if(actual!=sum)throw new IOException("Повреждённый пакет ADB");return new Packet(c,a,b,data);}
 private void open(String service)throws IOException{send(OPEN,1,0,(service+"\0").getBytes("UTF-8"));Packet p=receive();if(p.command!=OKAY||p.b!=1)throw new IOException("ADB отклонил службу");remote=p.a;}
 private Packet streamPacket()throws IOException{Packet p=receive();if(p.a!=remote||p.b!=1)throw new IOException("Чужой поток ADB");if(p.command==WRTE){if(pending.size()+p.data.length>2*1024*1024)throw new IOException("Слишком большой ответ ADB");pending.write(p.data);send(OKAY,1,remote,new byte[0]);}else if(p.command==CLSE){closed=true;send(CLSE,1,remote,new byte[0]);}else if(p.command!=OKAY)throw new IOException("Неожиданный пакет ADB");return p;}
 private void writeStream(byte[] data)throws IOException{for(int offset=0;offset<data.length;){int size=Math.min(maxData,data.length-offset);byte[] part=new byte[size];System.arraycopy(data,offset,part,0,size);send(WRTE,1,remote,part);while(true){Packet p=streamPacket();if(p.command==OKAY)break;if(closed)throw new IOException("ADB закрыл передачу");}offset+=size;}}
 private byte[] readStream(int length)throws IOException{while(pending.size()-cursor<length){if(closed)throw new EOFException("ADB закрыл ответ");streamPacket();}byte[] all=pending.toByteArray(),reply=new byte[length];System.arraycopy(all,cursor,reply,0,length);cursor+=length;if(cursor==all.length){pending.reset();cursor=0;}return reply;}
 String shell(String command)throws Exception{String marker="KONTUR_EXIT_"+Long.toHexString(new SecureRandom().nextLong()).replace("-","");open("shell:/system/bin/sh -c "+quote(command+"\nr=$?; printf '\\n"+marker+":%s\\n' \"$r\""));while(!closed)streamPacket();String value=new String(pending.toByteArray(),"UTF-8");int index=value.lastIndexOf("\n"+marker+":");if(index<0)throw new IOException("Результат команды не подтверждён; повтор автоматически не выполняется");String code=value.substring(index+marker.length()+2).trim();if(!code.equals("0"))throw new IOException("Команда завершилась с кодом "+code+": "+value.substring(0,Math.min(index,500)));return value.substring(0,index).replace("\r\n","\n").trim();}
 void push(String path,byte[] data)throws Exception{if(!path.matches("/data/local/tmp/(station-studio-install-[a-f0-9]{12,32}/(?:hybrid/)?[a-zA-Z0-9_.-]+|kontur-test-[a-f0-9]+)"))throw new IOException("Недопустимый путь установки");open("sync:");byte[] name=(path+",33216").getBytes("UTF-8");sync("SEND",name);for(int offset=0;offset<data.length;offset+=65536){int size=Math.min(65536,data.length-offset);byte[] chunk=new byte[size];System.arraycopy(data,offset,chunk,0,size);sync("DATA",chunk);}ByteBuffer done=ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN);done.put("DONE".getBytes("US-ASCII")).putInt((int)(System.currentTimeMillis()/1000));writeStream(done.array());byte[] result=readStream(8);String status=new String(result,0,4,"US-ASCII");int length=ByteBuffer.wrap(result,4,4).order(ByteOrder.LITTLE_ENDIAN).getInt();if(!status.equals("OKAY")){if(length<0||length>4096)throw new IOException("Ошибка ADB sync");throw new IOException("Передача отклонена: "+new String(readStream(length),"UTF-8"));}}
 private void sync(String tag,byte[] data)throws IOException{ByteBuffer b=ByteBuffer.allocate(8+data.length).order(ByteOrder.LITTLE_ENDIAN);b.put(tag.getBytes("US-ASCII")).putInt(data.length).put(data);writeStream(b.array());}
 static String quote(String value){return "'"+value.replace("'","'\\''")+"'";}
 static byte[] adbPublic(RSAPublicKey key){BigInteger n=key.getModulus(),r=BigInteger.ONE.shiftLeft(2048);ByteBuffer b=ByteBuffer.allocate(524).order(ByteOrder.LITTLE_ENDIAN);b.putInt(64).putInt(n.modInverse(BigInteger.ONE.shiftLeft(32)).negate().intValue());little(b,n,256);little(b,r.multiply(r).mod(n),256);b.putInt(key.getPublicExponent().intValue());return b.array();}
 private static void little(ByteBuffer b,BigInteger value,int count){for(int i=0;i<count;i++)b.put(value.shiftRight(i*8).byteValue());}
 static String base64(byte[] data){char[] alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".toCharArray();StringBuilder b=new StringBuilder();for(int i=0;i<data.length;i+=3){int count=Math.min(3,data.length-i),v=(data[i]&255)<<16;if(count>1)v|=(data[i+1]&255)<<8;if(count>2)v|=data[i+2]&255;b.append(alphabet[v>>>18]).append(alphabet[(v>>>12)&63]).append(count>1?alphabet[(v>>>6)&63]:'=').append(count>2?alphabet[v&63]:'=');}return b.toString();}
 @Override public void close()throws IOException{socket.close();}
}
